def _ceil_power_of_2(value: int) -> int:
    return 1 << (value - 1).bit_length()


def _block_size(value: int, maximum: int) -> int:
    return min(max(_ceil_power_of_2(value), 16), maximum)


def _matrix_strides(tensor: torch.Tensor, rows: int, cols: int):
    if tensor.numel() != rows * cols:
        raise RuntimeError(
            f"invalid LSTM weight with {tensor.numel()} elements, expected {rows * cols}"
        )
    if tensor.dim() == 2:
        if tensor.shape != (rows, cols):
            raise RuntimeError(
                f"invalid LSTM weight shape {tuple(tensor.shape)}, expected {(rows, cols)}"
            )
        return tensor.stride(0), tensor.stride(1)
    if tensor.dim() == 1:
        return cols, 1
    raise RuntimeError(f"LSTM weights must be 1-D or 2-D, got {tensor.dim()}-D")


def _bias_stride(tensor: torch.Tensor, size: int) -> int:
    if tensor.numel() != size:
        raise RuntimeError(
            f"invalid LSTM bias with {tensor.numel()} elements, expected {size}"
        )
    if tensor.dim() == 1:
        return tensor.stride(0)
    raise RuntimeError(f"LSTM bias tensors must be 1-D, got {tensor.dim()}-D")


def _param_group(params, index: int, has_biases: bool):
    group_size = 4 if has_biases else 2
    base = index * group_size
    if has_biases:
        return params[base], params[base + 1], params[base + 2], params[base + 3]
    return params[base], params[base + 1], params[base], params[base]


def _copy_hx_slice(src, dst, state_idx: int, batch_size: int, hidden_size: int):
    if dst.numel() == 0:
        return
    grid = (triton.cdiv(dst.numel(), _COPY_BLOCK),)
    with torch_device_fn.device(dst.device):
        _copy_hx_slice_kernel[grid](
            src,
            dst,
            state_idx,
            batch_size,
            hidden_size,
            src.stride(0),
            src.stride(1),
            src.stride(2),
            BLOCK=_COPY_BLOCK,
        )


def _store_hx_slice(src, dst, state_idx: int, batch_size: int, hidden_size: int):
    if src.numel() == 0:
        return
    grid = (triton.cdiv(src.numel(), _COPY_BLOCK),)
    with torch_device_fn.device(src.device):
        _store_hx_slice_kernel[grid](
            src,
            dst,
            state_idx,
            batch_size,
            hidden_size,
            dst.stride(0),
            dst.stride(1),
            dst.stride(2),
            BLOCK=_COPY_BLOCK,
        )


def _run_direction(
    layer_input,
    hx,
    cx,
    layer_output,
    final_h,
    final_c,
    params,
    state_idx: int,
    param_idx: int,
    out_feature_offset: int,
    input_size: int,
    hidden_size: int,
    batch_size: int,
    seq_len: int,
    has_biases: bool,
    reverse: bool,
):
    w_ih, w_hh, b_ih, b_hh = _param_group(params, param_idx, has_biases)
    w_ih_stride_r, w_ih_stride_c = _matrix_strides(w_ih, 4 * hidden_size, input_size)
    w_hh_stride_r, w_hh_stride_c = _matrix_strides(w_hh, 4 * hidden_size, hidden_size)
    b_ih_stride = _bias_stride(b_ih, 4 * hidden_size) if has_biases else 1
    b_hh_stride = _bias_stride(b_hh, 4 * hidden_size) if has_biases else 1

    h_work = torch.empty((batch_size, hidden_size), device=hx.device, dtype=hx.dtype)
    c_work = torch.empty((batch_size, hidden_size), device=cx.device, dtype=cx.dtype)
    h_next = torch.empty_like(h_work)
    c_next = torch.empty_like(c_work)
    _copy_hx_slice(hx, h_work, state_idx, batch_size, hidden_size)
    _copy_hx_slice(cx, c_work, state_idx, batch_size, hidden_size)
    if batch_size == 0:
        return

    block_h = _block_size(hidden_size, _BLOCK_H_MAX)
    # XPU's Triton pipeline overflows its event budget when one kernel carries
    # both projection loops plus the gate chain, and its inliner also fails
    # when a loop holds four ``tl.dot`` ops with a K tile below 64.  The step is
    # therefore split into three launches and the reduction tile is pinned at
    # 64, masking the edges instead.
    block_k = _BLOCK_K_MAX
    grid = (
        triton.cdiv(batch_size, _BLOCK_B),
        triton.cdiv(hidden_size, block_h),
    )
    # Per-gate partial sums in accumulator precision, consumed by the combine
    # kernel: gi = x @ w_ih.T, gh = h_prev @ w_hh.T.
    gi = torch.empty(
        (batch_size, 4 * hidden_size), device=layer_input.device, dtype=torch.float32
    )
    gh = torch.empty_like(gi)
    with torch_device_fn.device(layer_input.device):
        if input_size == 0:
            # An empty reduction contributes nothing (the bias is added by the
            # combine kernel), and a zero-trip loop is miscompiled on XPU, so
            # write the zeros directly instead of launching the projection.
            gi.zero_()
        for step in range(seq_len):
            seq_idx = seq_len - 1 - step if reverse else step
            if input_size != 0:
                _lstm_step_ih_kernel[grid](
                    layer_input,
                    w_ih,
                    gi,
                    seq_idx,
                    input_size,
                    hidden_size,
                    batch_size,
                    layer_input.stride(0),
                    layer_input.stride(1),
                    layer_input.stride(2),
                    w_ih_stride_r,
                    w_ih_stride_c,
                    gi.stride(0),
                    gi.stride(1),
                    BLOCK_B=_BLOCK_B,
                    BLOCK_H=block_h,
                    BLOCK_K=block_k,
                )
            _lstm_step_hh_kernel[grid](
                h_work,
                w_hh,
                gh,
                hidden_size,
                batch_size,
                h_work.stride(0),
                h_work.stride(1),
                w_hh_stride_r,
                w_hh_stride_c,
                gh.stride(0),
                gh.stride(1),
                BLOCK_B=_BLOCK_B,
                BLOCK_H=block_h,
                BLOCK_K=block_k,
            )
            _lstm_step_combine_kernel[grid](
                gi,
                gh,
                c_work,
                b_ih,
                b_hh,
                h_next,
                c_next,
                layer_output,
                seq_idx,
                out_feature_offset,
                hidden_size,
                batch_size,
                gi.stride(0),
                gi.stride(1),
                gh.stride(0),
                gh.stride(1),
                c_work.stride(0),
                c_work.stride(1),
                b_ih_stride,
                b_hh_stride,
                layer_output.stride(0),
                layer_output.stride(1),
                layer_output.stride(2),
                HAS_BIAS=has_biases,
                BLOCK_B=_BLOCK_B,
                BLOCK_H=block_h,
            )
            h_work, h_next = h_next, h_work
            c_work, c_next = c_next, c_work

    _store_hx_slice(h_work, final_h, state_idx, batch_size, hidden_size)
    _store_hx_slice(c_work, final_c, state_idx, batch_size, hidden_size)


def _validate_args(input, hx, params, has_biases, num_layers, dropout, bidirectional):
    if input.dim() != 3:
        raise RuntimeError("lstm: input must have 3 dimensions")
    if not isinstance(hx, (tuple, list)) or len(hx) != 2:
        raise RuntimeError("lstm expects two hidden states")
    if num_layers <= 0:
        raise RuntimeError("lstm: num_layers must be greater than zero")
    if not 0.0 <= dropout <= 1.0:
        raise RuntimeError("lstm: dropout probability must be between 0 and 1")
    if input.dtype not in (torch.float16, torch.bfloat16, torch.float32):
        raise NotImplementedError(
            "FlagGems lstm supports float16, bfloat16, and float32"
        )

    hx0, cx0 = hx
    if hx0.shape != cx0.shape:
        raise RuntimeError("lstm: hidden and cell states must have the same shape")
    if hx0.dim() != 3:
        raise RuntimeError("lstm: hidden and cell states must have 3 dimensions")
    num_directions = 2 if bidirectional else 1
    expected_states = num_layers * num_directions
    if hx0.shape[0] != expected_states:
        raise RuntimeError(
            f"lstm: expected {expected_states} hidden state rows, got {hx0.shape[0]}"
        )
    expected_params = expected_states * (4 if has_biases else 2)
    if len(params) != expected_params:
        raise RuntimeError(
            f"lstm: expected {expected_params} parameter tensors, got {len(params)}"
        )
    if hx0.device != input.device or cx0.device != input.device:
        raise RuntimeError(
            "lstm: input, hidden state, and cell state must share a device"
        )
    if hx0.dtype != input.dtype or cx0.dtype != input.dtype:
        raise RuntimeError(
            "lstm: input, hidden state, and cell state must share a dtype"
        )


def lstm(
    input,
    hx,
    params,
    has_biases=True,
    num_layers=1,
    dropout=0.0,
    train=False,
    bidirectional=False,
    batch_first=False,
):
    logger.debug("GEMS LSTM")
    _validate_args(input, hx, params, has_biases, num_layers, dropout, bidirectional)

    if batch_first:
        batch_size, seq_len, input_size = input.shape
        input_view = input.transpose(0, 1)
    else:
        seq_len, batch_size, input_size = input.shape
        input_view = input
    if seq_len == 0:
        raise RuntimeError("Expected sequence length to be larger than 0 in RNN")

    hx0, cx0 = hx
    hidden_size = hx0.shape[2]
    num_directions = 2 if bidirectional else 1
    final_h = torch.empty(
        (num_layers * num_directions, batch_size, hidden_size),
        device=input.device,
        dtype=input.dtype,
    )
    final_c = torch.empty_like(final_h)

    layer_input = input_view
    for layer in range(num_layers):
        layer_input_size = input_size if layer == 0 else hidden_size * num_directions
        layer_output = torch.empty(
            (seq_len, batch_size, hidden_size * num_directions),
            device=input.device,
            dtype=input.dtype,
        )
        for direction in range(num_directions):
            state_idx = layer * num_directions + direction
            reverse = direction == 1
            _run_direction(
                layer_input,
                hx0,
                cx0,
                layer_output,
                final_h,
                final_c,
                params,
                state_idx,
                state_idx,
                direction * hidden_size,
                layer_input_size,
                hidden_size,
                batch_size,
                seq_len,
                has_biases,
                reverse,
            )

        layer_input = layer_output
        if train and dropout != 0.0 and layer + 1 < num_layers:
            layer_input, _ = _dropout(layer_input, dropout, True)

    output = layer_input.transpose(0, 1) if batch_first else layer_input
    return output, final_h, final_c
